style.css:
@-moz-document domain("google.com") {
img[alt="Google"] {
        content: "";
        width: 272px; /* стандартна ширина логотипа */
        height: 92px; /* стандартна висота логотипа */
        background: linear-gradient(135deg, rgba(255,0,0,1) 10%, rgba(255,119,0,0.835) 23%, rgba(248,253,0,0.802) 40%, rgba(37,141,23,0.83) 60%, rgba(0,241,255,0.83) 84%);
        -webkit-mask-image: url(https://www.google.com/images/branding/googlelogo/2x/googlelogo_color_272x92dp.png);
        mask-image: url(https://www.google.com/images/branding/googlelogo/2x/googlelogo_color_272x92dp.png);
        -webkit-mask-size: cover;
        mask-size: cover;
        background-size: cover;
    }
}
